import {createContext,useContext,useState} from 'react'
import {createPortal} from 'react-dom'
const Context=createContext(null)
export function AuthProvider({children}) {
 const params=new URLSearchParams(location.search)
 const [signedIn,set]=useState(params.has('signedIn'))
 const [address,setAddress]=useState(params.has('login')?undefined:'0x0000000000000000000000000000000000000009')
 const [pending,setPending]=useState(null)
 const signIn=()=>new Promise((resolve,reject)=>setPending({resolve,reject,login:false}))
 const finish=(error)=>{
   const current=pending
   setPending(null)
   if(error) current.reject?.(new Error(error))
   else {setAddress('0x0000000000000000000000000000000000000009');set(true);current.resolve?.()}
 }
 const login=()=>setPending({login:true})
 return <Context.Provider value={{signedIn,address,signIn,isModalOpen:pending!==null,ready:true,login}}>
  {children}
  {pending && createPortal(<section aria-label="Wallet portal" style={{position:'fixed',inset:20,zIndex:9999,background:'white',padding:24}}>
   <button onClick={()=>finish(null)}>{pending.login?'Confirm login':'Confirm wallet sign-in'}</button>
   <button onClick={()=>finish('User cancelled sign-in')}>Cancel wallet sign-in</button>
   <button onClick={()=>finish('Wallet connection failed')}>Fail wallet sign-in</button>
  </section>,document.body)}
 </Context.Provider>
}
export const useAuth=()=>useContext(Context)
export const usePrivy=useAuth
export const usePrivyModalOpen=()=>useAuth().isModalOpen
